275	    container.appendChild(svg);
276	
277	    const xs = (x) => m.l + ((x - cfg.xMin) / (cfg.xMax - cfg.xMin)) * pw;
278	    const lyMin = Math.log10(cfg.yLog[0]), lyMax = Math.log10(cfg.yLog[1]);
279	    const ys = logScale
280	      ? (v) => m.t + ph - ((Math.log10(Math.max(v, cfg.yLog[0])) - lyMin) / (lyMax - lyMin)) * ph
281	      : (v) => m.t + ph - (Math.min(Math.max(v, 0), cfg.yLin[1]) / cfg.yLin[1]) * ph;
282	    const yTicks = logScale ? [10, 30, 100, 300, 1000, 3000, 10000].filter((v) => v >= cfg.yLog[0] && v <= cfg.yLog[1]) : cfg.yLinTicks;
283	
284	    for (const v of yTicks) {
285	      const y = ys(v);
286	      el("line", { x1: m.l, x2: m.l + pw, y1: y, y2: y, class: "gridline" }, svg);
287	      const t = el("text", { x: m.l - 8, y: y + 3.5, "text-anchor": "end" }, svg);
288	      t.textContent = v.toLocaleString("en-US");
289	    }
290	    el("line", { x1: m.l, x2: m.l + pw, y1: m.t + ph, y2: m.t + ph, class: "baseline-axis" }, svg);
291	    for (const x of cfg.xTicks) {
292	      const t = el("text", { x: xs(x), y: m.t + ph + 17, "text-anchor": "middle" }, svg);
293	      t.textContent = cfg.xFmt(x);
294	    }
295	    el("text", { x: m.l + pw / 2, y: H - 6, "text-anchor": "middle", class: "axis-title" }, svg).textContent = cfg.xLabel;
296	    const yt = el("text", { x: 14, y: m.t + ph / 2, "text-anchor": "middle", class: "axis-title", transform: `rotate(-90 14 ${m.t + ph / 2})` }, svg);
297	    yt.textContent = "Norethindrone, pg/mL";
298	
299	    if (cfg.before) cfg.before({ svg, xs, ys, m, pw, ph });
300	
301	    const N = 900;
302	    for (const s of cfg.series) {
303	      let d = "";
304	      for (let i = 0; i <= N; i++) {
305	        const x = cfg.xMin + ((cfg.xMax - cfg.xMin) * i) / N;
306	        d += (i ? "L" : "M") + xs(x).toFixed(2) + "," + ys(s.fn(x)).toFixed(2);
307	      }
308	      el("path", { d, class: "line " + s.cls }, svg);
309	    }
310	    if (cfg.after) cfg.after({ svg, xs, ys, m, pw, ph });
311	
312	    // hover layer: crosshair + tooltip
313	    const cross = el("line", { y1: m.t, y2: m.t + ph, class: "crosshair", visibility: "hidden" }, svg);
314	    const dots = cfg.series.map((s) => el("circle", { r: 4.5, class: "hover-dot", fill: `var(${s.color})`, visibility: "hidden" }, svg));
315	    const hit = el("rect", { x: m.l, y: m.t, width: pw, height: ph, fill: "transparent" }, svg);
316	    const tip = document.createElement("div");
317	    tip.className = "tip"; tip.hidden = true;
318	    container.appendChild(tip);
319	
320	    const show = (evt) => {
321	      const r = svg.getBoundingClientRect();
322	      const px = ((evt.clientX - r.left) / r.width) * W;
323	      const x = Math.min(cfg.xMax, Math.max(cfg.xMin, cfg.xMin + ((px - m.l) / pw) * (cfg.xMax - cfg.xMin)));
324	      const cx = xs(x);
325	      cross.setAttribute("x1", cx); cross.setAttribute("x2", cx); cross.setAttribute("visibility", "visible");
326	      let rows = "";
327	      cfg.series.forEach((s, i) => {
328	        const v = s.fn(x);
329	        dots[i].setAttribute("cx", cx); dots[i].setAttribute("cy", ys(v)); dots[i].setAttribute("visibility", "visible");
330	        rows += `<div class="row"><span><i class="sw" style="background:var(${s.color})"></i>${s.label}</span><span class="v">${fmt(v)}</span></div>`;
331	      });
332	      const extra = cfg.tipExtra ? cfg.tipExtra(x) : "";
333	      tip.innerHTML = `<div class="tip-head">${cfg.tipHead(x)}</div>${rows}${extra}`;
334	      tip.hidden = false;
335	      const cw = container.clientWidth, tw = tip.offsetWidth;
336	      const left = (cx / W) * cw;
337	      tip.style.left = (left + 14 + tw > cw ? left - 14 - tw : left + 14) + "px";
338	      tip.style.top = Math.max(0, ((m.t + 6) / H) * container.clientHeight) + "px";
339	    };
340	    const hide = () => {
341	      tip.hidden = true; cross.setAttribute("visibility", "hidden");
342	      dots.forEach((d) => d.setAttribute("visibility", "hidden"));
343	    };
344	    hit.addEventListener("pointermove", show);
345	    hit.addEventListener("pointerdown", show);
346	    hit.addEventListener("pointerleave", hide);
347	  }
348	
349	  // ---------- chart 1: single dose ----------
350	  const singleEl = document.getElementById("chart-single");
351	  function drawSingle() {
352	    lineChart(singleEl, {
353	      aria: "Norethindrone level after one 0.35 mg pill: two-compartment model, one-compartment model and label values",
354	      xMin: 0, xMax: 24, xTicks: [0, 4, 8, 12, 16, 20, 24], xFmt: (x) => x + " h", xLabel: "Hours after the pill",
355	      yLog: [10, 10000], yLin: [0, 7000], yLinTicks: [0, 1000, 2000, 3000, 4000, 5000, 6000, 7000],
356	      series: [
357	        { label: "Two compartments", cls: "s1", color: "--series-1", fn: (t) => single(MODELS.two, t) },
358	        { label: "One compartment", cls: "s2", color: "--series-2", fn: (t) => single(MODELS.one, t) },
359	      ],
360	      tipHead: (x) => `${x.toFixed(1)} h after the pill · pg/mL`,
361	      tipExtra: (x) => {
362	        if (Math.abs(x - LABEL.tmax) < 0.6) return `<div class="row"><span>Label peak</span><span class="v">${fmt(LABEL.cmax)} ± ${fmt(LABEL.cmaxSd)}</span></div>`;
363	        if (x > 23) return `<div class="row"><span>Label, 24 h</span><span class="v">${LABEL.c24} ± ${LABEL.c24Sd}</span></div>`;
364	        return "";
365	      },
366	      after: ({ svg, xs, ys }) => {
367	        const pts = [
368	          { x: LABEL.tmax, y: LABEL.cmax, sd: LABEL.cmaxSd, xsd: LABEL.tmaxSd },
369	          { x: 24, y: LABEL.c24, sd: LABEL.c24Sd },
370	        ];
371	        for (const p of pts) {
372	          el("line", { x1: xs(p.x), x2: xs(p.x), y1: ys(p.y - p.sd), y2: ys(p.y + p.sd), class: "errbar" }, svg);
373	          if (p.xsd) el("line", { x1: xs(p.x - p.xsd), x2: xs(p.x + p.xsd), y1: ys(p.y), y2: ys(p.y), class: "errbar" }, svg);
374	          el("circle", { cx: xs(p.x), cy: ys(p.y), r: 5, class: "pt" }, svg);
375	        }
376	      },
377	    });
378	  }
379	
380	  // table
381	  function stats(m) {
382	    let cmax = 0, tmax = 0;
383	    for (let t = 0; t <= 6; t += 0.001) { const c = single(m, t); if (c > cmax) { cmax = c; tmax = t; } }
384	    let auc = 0; const n = 4800;
385	    for (let i = 0; i < n; i++) { const a = (24 * i) / n, b = (24 * (i + 1)) / n; auc += ((single(m, a) + single(m, b)) / 2) * (b - a); }
386	    const c24 = single(m, 24);
387	    const half = Math.LN2 / Math.min(...m.map(([r]) => r));
388	    return { tmax, cmax, cavg: auc / 24, c24, half, drop: cmax / c24 };
389	  }
390	  const s1 = stats(MODELS.one), s2 = stats(MODELS.two);
391	  const within = (v, mean, sd) => Math.abs(v - mean) <= sd;
392	  const rows = [
393	    ["Time to peak", `${LABEL.tmax} ± ${LABEL.tmaxSd} h`, (s) => s.tmax.toFixed(2) + " h", (s) => within(s.tmax, LABEL.tmax, LABEL.tmaxSd)],
394	    ["Peak", `${fmt(LABEL.cmax)} ± ${fmt(LABEL.cmaxSd)}`, (s) => fmt(s.cmax), (s) => within(s.cmax, LABEL.cmax, LABEL.cmaxSd)],
395	    ["Average over 24 h", `${LABEL.cavg} ± ${LABEL.cavgSd}`, (s) => fmt(s.cavg), (s) => within(s.cavg, LABEL.cavg, LABEL.cavgSd)],
396	    ["Level at 24 h", `${LABEL.c24} ± ${LABEL.c24Sd}`, (s) => fmt(s.c24), (s) => within(s.c24, LABEL.c24, LABEL.c24Sd)],
397	    ["Fall from peak to 24 h", `${(LABEL.cmax / LABEL.c24).toFixed(0)}-fold`, (s) => s.drop.toFixed(1) + "-fold", (s) => Math.abs(s.drop / (LABEL.cmax / LABEL.c24) - 1) < 0.2],
398	    ["Half-life", `${LABEL.half} ± ${LABEL.halfSd} h`, (s) => s.half.toFixed(1) + " h", (s) => within(s.half, LABEL.half, LABEL.halfSd)],
399	  ];
400	  document.getElementById("tbl-single").innerHTML = rows.map(([name, lab, f, ok]) =>
401	    `<tr><td>${name}</td><td>${lab}</td><td class="${ok(s1) ? "" : "miss"}">${f(s1)}${ok(s1) ? "" : " ✕"}</td><td class="${ok(s2) ? "" : "miss"}">${f(s2)}${ok(s2) ? "" : " ✕"}</td></tr>`
402	  ).join("") + `<tr><td colspan="4" style="font-family:var(--font-body);font-size:12.5px;color:var(--muted);white-space:normal">Concentrations in pg/mL. ✕ marks a value outside the label's mean ± SD (or more than 20% off for the fall).</td></tr>`;
403	
404	  // ---------- chart 2: late pill ----------
405	  const DUE = 240; // the late pill is due on day 10, after levels have settled
406	  const onTime = Array.from({ length: 16 }, (_, i) => 24 * i);
407	  const usualLow = multi(MODELS.two, onTime, DUE);
408	  let late = 3; // hours, or "skip"
409	
410	  const scenarioDoses = () => onTime.flatMap((d) => (d !== DUE ? [d] : late === "skip" ? [] : [d + late]));
411	  const lateLabel = () => (late === "skip" ? "Pill skipped" : late === 0 ? "On time" : `${late} h late`);
412	
413	  const lateEl = document.getElementById("chart-late");
414	  function drawLate() {
415	    const doses = scenarioDoses();
416	    const f = (x) => multi(MODELS.two, doses, DUE + x);
417	    const g = (x) => multi(MODELS.two, onTime, DUE + x);
418	    lineChart(lateEl, {
419	      aria: `Norethindrone level over several days with one pill ${lateLabel().toLowerCase()}, compared with all pills on time`,
420	      xMin: -36, xMax: 72, xTicks: [-24, 0, 24, 48, 72], xFmt: (x) => (x > 0 ? "+" : "") + x + " h",
421	      xLabel: "Hours since the late pill was due",
422	      yLog: [10, 10000], yLin: [0, 6000], yLinTicks: [0, 1000, 2000, 3000, 4000, 5000, 6000],
423	      series: [
424	        { label: lateLabel(), cls: "s1", color: "--series-1", fn: f },
425	        { label: "On time", cls: "s0", color: "--baseline", fn: g },
426	      ],
427	      tipHead: (x) => `${x >= 0 ? "+" : ""}${x.toFixed(1)} h · pg/mL`,
428	      before: ({ svg, xs, ys, m, ph }) => {
429	        // shade where the late scenario sits below the usual daily low
430	        let start = null;
431	        const step = 0.05;
432	        for (let x = -36; x <= 72 + step; x += step) {
433	          const below = x <= 72 && f(x) < usualLow * 0.999;
434	          if (below && start === null) start = x;
435	          if (!below && start !== null) {
436	            el("rect", { x: xs(start), y: m.t, width: Math.max(1, xs(x) - xs(start)), height: ph, class: "shade" }, svg);
437	            start = null;
438	          }
439	        }
440	        // pill markers along the bottom
441	        for (const d of onTime) {
442	          const x = d - DUE;
443	          if (x < -36 || x > 72 || d === DUE) continue;
444	          el("circle", { cx: xs(x), cy: m.t + ph - 6, r: 3.5, class: "pill-mark" }, svg);
445	        }
446	        if (late !== "skip") el("circle", { cx: xs(late), cy: m.t + ph - 6, r: 4.5, class: "pill-late" }, svg);
447	      },
448	      after: ({ svg, xs, ys, m, pw }) => {
449	        const y = ys(usualLow);
450	        el("line", { x1: m.l, x2: m.l + pw, y1: y, y2: y, class: "ref" }, svg);
451	        const t = el("text", { x: m.l + pw - 4, y: y - 6, "text-anchor": "end", class: "ref-label" }, svg);
452	        t.textContent = `usual daily low, ${fmt(usualLow)}`;
453	      },
454	    });
455	
456	    // stats over the window from the due time onward
457	    let min = Infinity, tMin = 0, below = 0, belowOnTime = 0;
458	    const step = 0.02;
459	    for (let x = 0; x <= 72; x += step) {
460	      const v = f(x), b = g(x);
461	      if (v < min) { min = v; tMin = x; }
462	      if (v < usualLow * 0.999) below += step;
463	      if (b < usualLow * 0.999) belowOnTime += step;
464	    }
465	    const extra = Math.max(0, below - belowOnTime);
466	    const pct = Math.max(0, (1 - min / usualLow) * 100);
467	    document.getElementById("st-low").innerHTML = `${fmt(usualLow)} <small>pg/mL</small>`;
468	    document.getElementById("st-min").innerHTML = `${fmt(min)} <small>pg/mL</small>`;
469	    document.getElementById("st-min-d").textContent = pct > 0.5 ? `${pct.toFixed(0)}% below the usual low, at +${tMin.toFixed(1)} h` : "no lower than usual";
470	    document.getElementById("st-time").innerHTML = `${fmtH(extra)} <small>h</small>`;
471	    document.getElementById("legend-late-label").textContent = lateLabel();
472	
473	    const s = document.getElementById("summary");
474	    if (pct <= 0.5) s.innerHTML = "With every pill on time, levels never drop below the usual daily low.";
475	    else s.innerHTML = `${late === "skip" ? "Skipping the pill" : `Taking the pill <strong>${late} h late</strong>`}, levels fall to <strong>${fmt(min)} pg/mL</strong>, <strong>${pct.toFixed(0)}% below</strong> the usual daily low, and stay below it for <strong>${fmtH(extra)} h</strong>.`;
476	
477	    const lv = document.getElementById("late-val");
478	    lv.textContent = late === "skip" ? "skipped" : late === 0 ? "on time" : `${late} h late`;
479	    document.querySelectorAll("[data-late]").forEach((b) => b.setAttribute("aria-pressed", String(String(late) === b.dataset.late)));
480	  }
481	
482	  // ---------- controls ----------
483	  const slider = document.getElementById("late");
484	  slider.addEventListener("input", () => { late = Number(slider.value); drawLate(); });
485	  document.querySelectorAll("[data-late]").forEach((b) => b.addEventListener("click", () => {
486	    late = b.dataset.late === "skip" ? "skip" : Number(b.dataset.late);
487	    if (late !== "skip") slider.value = late;
488	    drawLate();
489	  }));
490	  const setScale = (log) => {
491	    logScale = log;
492	    document.getElementById("scale-log").setAttribute("aria-pressed", String(log));
493	    document.getElementById("scale-lin").setAttribute("aria-pressed", String(!log));
494	    drawSingle(); drawLate();
495	  };
496	  document.getElementById("scale-log").addEventListener("click", () => setScale(true));
497	  document.getElementById("scale-lin").addEventListener("click", () => setScale(false));
498	
499	  const redraw = () => { drawSingle(); drawLate(); };
500	  let raf = 0;
501	  new ResizeObserver(() => { cancelAnimationFrame(raf); raf = requestAnimationFrame(redraw); }).observe(document.querySelector("main"));
502	  redraw();
503	})();
504	</script>
