rep("""        <span><svg width="22" height="10" aria-hidden="true"><line x1="1" y1="5" x2="21" y2="5" stroke="var(--combo)" stroke-width="2.5" stroke-linecap="round"/></svg>Levonorgestrel, no SHBG</span>""",
    """        <span><svg width="22" height="10" aria-hidden="true"><line x1="1" y1="5" x2="21" y2="5" stroke="var(--combo)" stroke-width="2.5" stroke-linecap="round"/></svg>Levonorgestrel, with SHBG</span>
        <span><svg width="22" height="10" aria-hidden="true"><line x1="1" y1="5" x2="21" y2="5" stroke="var(--combo)" stroke-width="1.5" stroke-dasharray="6 5" opacity="0.5"/></svg>Without SHBG</span>""")

