rep("""<span><svg width="22" height="10" aria-hidden="true"><line x1="1" y1="5" x2="21" y2="5" stroke="var(--combo)" stroke-width="2.5" stroke-linecap="round"/></svg>Combined pill (no SHBG)</span>""",
    """<span><svg width="22" height="10" aria-hidden="true"><line x1="1" y1="5" x2="21" y2="5" stroke="var(--combo)" stroke-width="2.5" stroke-linecap="round"/></svg>Combined pill (with SHBG)</span>""")
rep("""<h3><i class="dot" style="background:var(--combo)"></i>Combined pill (no SHBG)</h3>""",
